    de,tr,cat,level,defde,deftr,exde1,extr1,exde2,extr2=p
    art=de.split(' ',1)[0] if de.startswith(('der ','die ','das ')) else ''
    term=de.split(' ',1)[1] if art else de
    term_id=re.sub(r'[^a-z0-9]+','-',unicodedata.normalize('NFKD',term.lower().replace('ß','ss')).encode('ascii','ignore').decode()).strip('-')
    if any(t['id']==term_id for t in terms): term_id=f'{term_id}-{i}'
    kind='isim' if art else ('fiil' if de.endswith(('en','ern')) else 'bağlaç / zarf')
    terms.append(dict(id=term_id,de=de,tr=tr,article=art,word=term,plural=None,type=kind,category=cat,level=level,definitionDE=defde,definitionTR=deftr,examples=[dict(de=exde1,tr=extr1),dict(de=exde2,tr=extr2)],legal=cat!='general'))
