for c in categories:
    ids=[t['id'] for t in terms if t['category']==c['id']]
    lists.append(dict(id='cat-'+c['id'],name=c['tr'],subtitle=c['de'],description=c['description'],category=c['id'],level='Karma',ids=ids,kind='category'))
for level in ['A1','A2','B1','B2','C1']:
    ids=[t['id'] for t in terms if t['category']=='general' and t['level']==level]
    if ids: lists.append(dict(id='general-'+level,name=level+' Genel Almanca',subtitle='Allgemeines Deutsch · '+level,description=level+' seviyesinde akademik ve günlük kelimeler',category='general',level=level,ids=ids,kind='general'))
for listid,name,sub,keys in [
    ('dava','Dava ve Mahkeme Terminolojisi','Prozesswortschatz',['zivilprozess','strafprozess']),
    ('temel','Hukuka İlk Adım','Grundbegriffe',['allgemein','zivil']),
    ('kontrat','Sözleşme ve Borçlar','Verträge und Verpflichtungen',['vertrag','schuldrecht']),
    ('is','Çalışma Hayatı','Arbeitswelt',['arbeits','gesellschaft']),
    ('akademik','Akademik Almanca','Akademische Sprache',['general'])]:
    ids=[t['id'] for t in terms if t['category'] in keys]
    lists.append(dict(id='theme-'+listid,name=name,subtitle=sub,description='Tematik seçki',category=keys[0],level='Karma',ids=ids,kind='featured'))
(root/'assets'/'terms.js').write_text('/* Başlangıç sözlüğü — hukuki karşılıklar öğrenme amaçlıdır. */\nwindow.LEXHUKUK_DATA = '+json.dumps({'terms':terms,'categories':categories,'lists':lists},ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
(root/'data'/'terms.json').write_text(json.dumps(terms,ensure_ascii=False,indent=2),encoding='utf-8')
print('TERMS:',len(terms),'CATEGORIES:',len(categories),'LISTS:',len(lists))
